<template><section v-if="content&&['free','premium'].includes(content.tier)" class="mvp-access-note" :class="{'is-locked':locked}"><span class="mvp-access-note__icon"><sf-icon :name="locked?'lock':content.tier==='premium'?'membership':'check'" :size="18"/></span><div><strong>{{ content.tier==='free'?'Free to enjoy':locked?'Included with Premium':'Your Premium access is ready' }}</strong><p>{{ message }}</p></div><button v-if="locked" type="button" @click="$emit('action','start-content:'+content.id)">Explore <span aria-hidden="true">→</span></button></section></template>
<script>
import {SfIcon} from '@/design-system'
export default {components:{SfIcon},props:{content:Object},computed:{locked(){return this.content.tier==='premium'&&!this.content.access?.allowed},message(){if(this.content.tier==='free')return 'Start this workout with your Free account.';if(!this.locked)return 'Start whenever you’re ready. No conversation allowance used.';return{world_tour:'Discover more scenery with Premium World Tours.',training_program:'Follow a structured series of Premium workouts.',course:'Bring more variety to your routine with Premium courses.'}[this.content.contentType]||'Explore your Premium benefits.'}}}
</script>
<style scoped>.mvp-access-note{display:flex;align-items:flex-start;gap:10px;border:1px solid var(--sf-content-edge);border-radius:16px;background:var(--sf-content-surface);padding:13px 12px;margin:12px 0;color:var(--sf-text)}.mvp-access-note.is-locked{background:linear-gradient(125deg,#f9e6df66,#f4ecff44),var(--sf-content-surface)}.mvp-access-note__icon{color:var(--sf-action);flex-shrink:0;margin-top:2px}.mvp-access-note>div{flex:1;min-width:0}.mvp-access-note strong{font-size:13px;line-height:20px;font-weight:600}.mvp-access-note p{font-size:12px!important;line-height:19px!important;color:var(--sf-text-secondary);margin:4px 0 0!important}.mvp-access-note button{font:600 12px/20px var(--sf-font-family);background:transparent;color:var(--sf-action);border:0;padding:0 0 0 5px;min-height:44px;cursor:pointer;align-self:center}</style>
